import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Config/Routes/route_name.dart';import 'package:zan/Features/Home/presentation/manager/home_cubit.dart';import 'package:zan/main.dart';import '../../../../Config/Assets/images_test.dart';import '../../../../Core/Resources/app_fonts.dart';import '../../../../Core/Utils/Extensions/widget_extension.dart';import '../../../../Core/Utils/Widget/Images/build_image.dart';import '../Manager/product_details_cubit.dart';import '../components/build_button_add_cart.dart';import '../components/tab_bar_products.dart';class ProductDetailsScreen extends StatelessWidget {  final int id;  const ProductDetailsScreen({super.key, required this.id});  @override  Widget build(BuildContext context) {    return BlocProvider(      create: (context) => ProductDetailsCubit(),      child: Scaffold(        appBar: AppBar(),        body: [          SliverToBoxAdapter(            child: BuildImageAssets(              width: 1.sw,              height: .3.sh,              fit: BoxFit.fill,              png: AppImagesTest.testPhoto,            ),          ),          SliverToBoxAdapter(            child: Padding(              padding: const EdgeInsets.all(8.0),              child: Row(                children: [                  InkWell(                      onTap: () {                        kNavigationService.navigateTo(AppRoutes.screen3D);                      },                      child: Text(                        "3D",                        style: AppTextStyles.h6Bold,                      )),                  20.horizontalSpace,                  InkWell(                      onTap: () {                        kNavigationService.navigateTo(AppRoutes.aRViewScreen);                      },                      child: Text(                        "3D(AR)",                        style: AppTextStyles.h6Bold,                      )),                ],              ),            ),          ),          TabBarProducts()        ].styledAppPages(withScroll: true).styledAppPages(withPadding: true),        persistentFooterButtons: [BuildButtonAddCart()],      ),    );  }}